 }
 const snapshotChecks=rawSnapshots.map((snap,index)=>{
  const s=snap.raw.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n");
  const mn=s.match(/Move number: (\\d+)/),caps=s.match(/Captured by Black: (\\d+); by White: (\\d+)/),km=s.match(/Ko point: ([A-HJ][1-9]|none)/);
