function inspect(raw){const s=raw.content.filter(x=>x.type==="text").map(x=>x.text).join("\n");const cols="ABCDEFGHJ";const b={};for(const l of s.split("\n")){const m=l.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m){m[2].split(/\s+/).forEach((v,i)=>b[cols[i]+m[1]]=v)}}const ns=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c)};let seen=new Set(),groups=[],regions=[];for(const p of Object.keys(b)){if(seen.has(p))continue;const c=b[p],q=[p],stones=[],libs=new Set(),border=new Set();seen.add(p);while(q.length){let v=q.pop();stones.push(v);for(const n of ns(v)){if(b[n]===c&&!seen.has(n)){seen.add(n);q.push(n)}else if(b[n]===".")libs.add(n);else if(b[n]!==c)border.add(b[n])}}if(c===".")regions.push({points:stones.sort(),boundary:[...border],owner:border.size===1?[...border][0]:null});else groups.push({color:c,stones:stones.sort(),liberties:[...libs].sort()})}return{board:b,groups,regions,stoneCounts:{B:Object.values(b).filter(x=>x==="X").length,W:Object.values(b).filter(x=>x==="O").length},area:{B:Object.values(b).filter(x=>x==="X").length+regions.filter(x=>x.owner==="X").reduce((s,x)=>s+x.points.length,0),W:Object.values(b).filter(x=>x==="O").length+regions.filter(x=>x.owner==="O").reduce((s,x)=>s+x.points.length,0),mixed:regions.filter(x=>!x.owner).reduce((s,x)=>s+x.points.length,0)}}}


// Replays supplied recorded moves only. Never selects, ranks, or searches moves.
// Missing intermediate raw responses are not reconstructed evidence.
function verifyRecorded(actualMoves, rawSnapshots) {
 const cols="ABCDEFGHJ", b=Object.fromEntries([...cols].flatMap(c=>Array.from({length:9},(_,i)=>[c+(i+1),"."])));
 const neighbors=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c)};
 const group=p=>{const q=[p],seen=new Set([p]),libs=new Set();while(q.length)for(const n of neighbors(q.pop())){if(b[n]===".")libs.add(n);else if(b[n]===b[p]&&!seen.has(n)){seen.add(n);q.push(n)}}return{stones:[...seen].sort(),libs:[...libs].sort()}};
 const inspectBoard=()=>inspect({content:[{type:"text",text:Array.from({length:9},(_,i)=>{const y=9-i;return " "+y+" "+[...cols].map(c=>b[c+y]).join(" ")+" "+y}).join("\n")}]});
 let capB=0,capW=0,ko=null;
 const positions=[{afterMove:0,captures:{B:0,W:0},ko:null,inspection:inspectBoard()}],captureEvents=[];
 for(const [i,m] of actualMoves.entries()){
  if(m.number!==i+1||m.color!==(m.number%2?"B":"W"))throw Error("wrong move number or turn");
  if(m.move==="pass")ko=null;
  else {
   if(b[m.move]!==".")throw Error("occupied or invalid point "+m.number);
   if(m.move===ko)throw Error("ko "+m.number);
   b[m.move]=m.color==="B"?"X":"O";
   const opp=m.color==="B"?"O":"X";let captured=[];
   for(const n of neighbors(m.move))if(b[n]===opp){const g=group(n);if(!g.libs.length){captured.push(...g.stones);for(const p of g.stones)b[p]="."}}
   const g=group(m.move);if(!g.libs.length)throw Error("suicide "+m.number);
   if(m.color==="B")capB+=captured.length;else capW+=captured.length;
   ko=captured.length===1&&g.stones.length===1&&g.libs.length===1?captured[0]:null;
   if(captured.length)captureEvents.push({...m,captured:captured.sort()});
  }
  positions.push({afterMove:m.number,captures:{B:capB,W:capW},ko,inspection:inspectBoard()});
 }
 const snapshotChecks=rawSnapshots.map((snap,index)=>{
  const s=snap.raw.content.filter(x=>x.type==="text").map(x=>x.text).join("\n");
  const mn=s.match(/Move number: (\d+)/),caps=s.match(/Captured by Black: (\d+); by White: (\d+)/),km=s.match(/Ko point: ([A-HJ][1-9]|none)/);
  if(!mn||!caps||!km)throw Error("missing snapshot fields "+index);
  const afterMove=+mn[1]-1,p=positions[afterMove],obs=inspect(snap.raw);
  if(!p||Object.keys(obs.board).length!==81)throw Error("incomplete or out-of-range snapshot "+index);
  const check={snapshot:index,kind:snap.kind,afterMove,boardMatches:Object.keys(b).every(q=>p.inspection.board[q]===obs.board[q]),capturesMatch:+caps[1]===p.captures.B&&+caps[2]===p.captures.W,koMatches:km[1]===(p.ko||"none"),moveNumberMatches:true};
  if(snap.kind==="play"){
   const a=actualMoves[afterMove-2],z=actualMoves[afterMove-1],reply=s.match(/Your opponent played ([A-HJ][1-9])\./);
   if(!a||a.color!=="B"||a.move!==snap.submitted||!z||z.color!=="W"||z.move!==(reply?reply[1]:/Your opponent passed\./.test(s)?"pass":null))throw Error("recorded response mismatch "+index);
  }
  if(Object.values(check).includes(false))throw Error("snapshot mismatch "+index);
  return check;
 });
 return{actualMoves,captureEvents,snapshotChecks,totalMoves:actualMoves.length,totalPreservedRawSnapshots:rawSnapshots.length,allMatched:true,finalCaptures:{B:capB,W:capW},finalInspection:positions.at(-1).inspection,positions};
}
